from pathlib import Path
import json
out=Path(__file__).with_name('gpt-part1.json')
items=[]
def add(number,title,composition,characters,lighting,mood,avoid):
    items.append(dict(number=number,title=title,composition=composition,characters=characters,lighting=lighting,mood=mood,avoid=avoid))
add(1,'Областной военкомат',
'Создай средний план в помещении областного военкомата ранним утром 19 ноября 1990 года. Герой находится немного правее центра, виден до бёдер; ещё несколько призывников образуют спокойный размытый второй план. Оставь перед взглядом героя свободное пространство слева: он слушает сообщение за границей изображения. Непритязательная обстановка советского учреждения служит фоном, а не отдельным историческим утверждением о конкретном здании.',
'У героя обычная гражданская куртка, старые порванные джинсы и волосы до армейской стрижки. Внешность, цвет и крой одежды бери из приложенного референса. Плечи чуть напряжены, руки спокойно опущены; одежда должна естественно лежать на теле. Остальные призывники выглядят отдельными людьми, без одинаковых лиц.',
'Мягкий холодный утренний свет сбоку; приглушённые серо-синие и землистые оттенки. Лицо остаётся читаемым в небольшом размере.',
'Главное ощущение — момент, когда человек узнаёт о трёх годах службы и ещё пытается принять новость. Мимика сдержанная, без театрального потрясения.',
'Не изображай героя уже в форме, с обритой головой, с оружием или наручниками. Не добавляй лозунги, гербы крупным планом, адрес, фамилии, печати, часы с датой и придуманных родственников.')
add(2,'Три года вдали от дома',
'Создай крупный портрет того же героя сразу после известия о трёх годах службы. В кадре голова, плечи и верх гражданской куртки; лицо немного смещено от центра, взгляд направлен вниз и в сторону. По краю кадра остаётся свободное пространство, усиливающее ощущение отчуждения. Фон военкомата с несколькими нечёткими фигурами должен быть обобщённым и значительно менее подробным, чем лицо.',
'Сохрани узнаваемую геометрию лица, возраст по референсу, нос, подбородок и причёску из первой картинки. Плечи слегка опущены, губы сомкнуты, глаза не смотрят прямо на зрителя. Передай усталую сосредоточенность через небольшое напряжение бровей, без слёз.',
'Тот же холодный боковой свет, что в первой сцене. Мягкие тени, различимая фактура куртки, без глянцевой кожи и рекламного портретного света.',
'Изображение передаёт личное ощущение тяжести новости и будущей разлуки. Герой остаётся в реальном помещении, а не внутри буквальной метафоры.',
'Не рисуй решётки, тюрьму, цепи, мечты о доме, призрачных родственников, облака мыслей, крупные надписи «три года» или другой символический реквизит. Не делай героя старше или моложе.')
add(3,'Вечерний поезд',
'Покажи один зафиксированный момент вечерней посадки в поезд в Минске. В вертикальную композицию входят часть платформы, открытый вход пассажирского вагона и герой на ступеньке. Он расположен в центральной трети; корпус и ноги не обрезаны, поручень и опора ступни хорошо различимы. Несколько призывников позади обозначают очередь, но не перетягивают внимание. Не воспроизводи конкретный фасад вокзала.',
'Герой в той же гражданской куртке, старых джинсах и обуви по референсу. Одной рукой держится за поручень, одна нога стоит на ступеньке, вес тела выглядит убедительно. Это одно положение тела, без дублирования конечностей и размытого следа. Одежда у остальных призывников различается.',
'Холодный вечерний свет платформы противопоставлен мягкому тёплому свету из открытого тамбура. Металл матовый, без декоративного свечения; лицо героя достаточно освещено.',
'Переход из знакомой жизни в неизвестность: спокойная серьёзность, никакой торжественной отправки.',
'Не добавляй провожающую семью, цветы, оркестр, прощальные объятия, читаемые объявления, номера вагонов, марку локомотива и флаги. Герой ещё не острижен и не переодет в форму.')
add(4,'В вагоне',
'Создай общий план пассажирского вагона изнутри. Высокий кадр должен соединять ближайшую скамью, проход и небольшой фрагмент дальнего пространства, без чрезмерного широкоугольного искажения. Герой сидит у края композиции и читается как наблюдатель. Несколько призывников образуют второй план; один держит неприметную ёмкость, связанную с упомянутым в рассказе спиртным. Не превращай вагон в ресторан или праздничное застолье.',
'Все призывники в гражданской одежде. Герой сохраняет прежнюю куртку, причёску и внешность. Его руки пустые, поза закрытая и усталая. У соседей разные лица и естественные положения рук; ёмкость без этикетки и без акцента на конкретном напитке.',
'Неброский тёплый вагонный свет, тёмные окна, приглушённая охристо-коричневая палитра с прохладными тенями. Не делай помещение ярким и уютным.',
'Несмотря на спиртное, общее настроение тяжёлое: ожидание долгой службы и разлуки. Никаких весёлых улыбок и пьяной карикатурности.',
'Не показывай героя пьющим: источник этого не подтверждает. Не добавляй драку, карты, музыкальные инструменты, бренды алкоголя, роскошную еду, современную электронику и читаемые плакаты.')
add(5,'Путь в неизвестность',
'Создай близкий портрет героя у тёмного окна поезда. Лицо находится в левой половине изображения и обращено к стеклу справа; взгляд уходит в ночь. В кадре только голова, плечо, часть куртки и край окна. Отражение лица очень слабое и неполное: оно подчёркивает стекло, но не выглядит вторым человеком. Пространство вагона остаётся узнаваемым по нескольким деталям, а не по обилию предметов.',
'Это тот же герой с неизменными чертами лица и волосами до стрижки. Поза естественная, шея не вывернута, руки не прижаты драматически к стеклу. Сдержанная мимика: человек задумался о том, что его ждёт.',
'Мягкий тёплый свет из вагона касается щеки и воротника; со стороны окна тени холоднее. За стеклом почти сплошная темнота, без выдуманных городов и достопримечательностей.',
'Тишина и неопределённость передаются пространством кадра и взглядом, без буквальных символов судьбы.',
'Не добавляй фотографии семьи в руке, телефон, часы, надписи на стекле, маршрутную карту, слёзы и грозовую драматизацию. Отражение не должно менять лицо или раздваивать глаза.')
add(6,'Ночное прибытие в Симферополь',
'Создай общий вертикальный план ночной зоны прибытия поезда в Симферополе. Часть пассажирского вагона занимает один край кадра; в центре и на переднем плане стоят несколько прибывших призывников. Герой находится ближе к зрителю и отделён от остальных небольшим просветом. Изображение должно читаться как короткая остановка после дороги, без дополнительной сцены встречи или построения.',
'Призывники в гражданских куртках; герой сохраняет джинсы, волосы и внешность предыдущих изображений. Усталые спокойные лица, обычные позы людей после поездки. Не делай всех одинаково повернувшимися к зрителю.',
'Тёмное окружение и несколько редких станционных источников света. Холодная серо-синяя атмосфера, локальные тёплые пятна возле вагона. Детали лиц остаются различимыми, но ночь не превращается в дневной свет.',
'Незнакомое место, усталость после дороги, отсутствие понимания дальнейшего маршрута.',
'Не рисуй точный фасад вокзала, снегопад, дождь, узнаваемый памятник, автобус, встречающих родственников и моряков, приветствующих героя. Не добавляй читаемую надпись «Симферополь», дату или номер поезда.')
add(7,'На распределительный пункт',
'Покажи ночной двор распределительного пункта после доставки призывников на грузовиках. В кадре часть кузова одного грузовика и герой у его края; другие призывники остаются в глубине. Выбери ракурс в три четверти сбоку, чтобы было понятно, где кузов, земля и опора для ног. Высокая композиция сохраняет фигуру героя целиком и не прижимает его к краю.',
'Один конкретный момент: герой спускается с кузова, держась рукой за устойчивую опору; нога находится на нижней ступени. Куртка, старые джинсы, обувь и волосы совпадают с предыдущими сценами. Положение корпуса показывает реальное распределение веса, без прыжка и акробатики.',
'Редкое наружное освещение двора, глубокие холодные тени, мягкий свет на фигуре. Фактура грузовика неброская, технические детали обобщены.',
'Бытовой эпизод прибытия в незнакомое место. Напряжение передаётся сдержанно, без боевой атмосферы.',
'Не указывай марку грузовика, регистрационный знак, номер воинской части и точный вид ворот. Не добавляй оружие, конвой, наручники, боевые прожекторы, дождь и выдуманные дорожные знаки.')
add(8,'Новая казарма',
'Создай общий вид казармы распределительного пункта. Двухъярусные кровати образуют перспективу в глубину; между ними остаётся понятный проход. Герой стоит в ближайшей части прохода, а в среднем и дальнем плане несколько небольших групп призывников знакомятся. В вертикальном кадре видны верхние ярусы, фигуры людей и часть пола, но помещение не должно выглядеть огромным залом с бесконечными рядами.',
'Все новоприбывшие в гражданской одежде. Герой узнаваем по прежней куртке, волосам и старым джинсам. Лица и позы массовки разные: один сидит, другой стоит боком к собеседнику. Не кодируй происхождение карикатурными чертами и не придумывай персональные истории.',
'Неброский общий свет помещения, приглушённые землистые и серые оттенки. Лицо героя немного заметнее фона за счёт контраста, а не искусственного ореола.',
'Шумное незнакомое пространство, общая усталость и вынужденное соседство. Сцена остаётся повседневной.',
'Не добавляй морскую форму на герое, плакаты с лозунгами, читаемые именные таблички, вымышленное оружие, личные фотографии и современную мебель. Не делай кадр парадным групповым портретом.')
add(9,'Второй ярус',
'Покажи героя уже лежащим на верхней койке двухъярусной кровати в первую ночь в Симферополе. Выбери боковой ракурс чуть снизу: верхняя койка с героем занимает основную часть изображения, а ниже виден край нижней койки, ясно обозначающий второй ярус. Фигура помещается на матрасе естественно, без невозможных изгибов и слишком короткой кровати.',
'Герой остаётся в гражданской куртке и старых джинсах, волосы ещё не острижены. Он лежит слегка свернувшись, руки устроены спокойно, лицо усталое. Куртка не превращается в шинель или бушлат. Сохрани устройство этой кровати для связанных сцен, не меняя число ярусов.',
'Холодный приглушённый ночной свет, мягкие тени между металлическими деталями. Лицо различимо, но общая среда остаётся тёмной. Не добавляй пар изо рта и лёд: источник говорит лишь о прохладе.',
'Человек пытается устроиться в непривычном месте и согреться одеждой; без сентиментальной театральности.',
'Не изображай нижнюю койку вместо верхней, морскую форму, обритую голову, тёплое одеяло поверх героя как главный предмет, ночную драку или санитаров: это другая сцена рассказа.')
add(10,'Проверки по списку',
'Создай общий план утреннего построения во дворе распределительного пункта. Ряд призывников уходит по диагонали в глубину; герой находится в ближайшей трети кадра, лицо видно в три четверти. Проверяющий с листом расположен сбоку, чтобы его фигура не перекрывала героя. Простой двор и обобщённые здания занимают второстепенное место.',
'На герое прежние гражданская куртка, старые порванные джинсы и волосы до стрижки. Он стоит спокойно, немного устало, как остальные. Лист в руках проверяющего не содержит читаемых фамилий и данных. Люди не позируют зрителю и не стоят идеально одинаковыми клонами.',
'Ровный прохладный утренний свет, мягкие тени, приглушённая палитра. Сдержанная фактура ткани и земли, без декоративной золотой дымки.',
'Ожидание и однообразие повторных проверок. Выражение героя передаёт терпение и усталость, без протеста или конфликта.',
'Не превращай проверку по списку в парад, строевую тренировку или наказание. Не добавляй оружие, часы с датой, меню, еду в руках, конкретные погодные явления и ещё не выданную морскую форму.')
out.write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('Saved',len(items),'scene-specific prompt drafts:',out)
